<div class="row g-5 my-3" data-component="dbim_full_layout">
    <div class="col-md-12 col-lg-4 stickyBox">
        <div class="visionbox" style="background: #ebeaea; border-radius: 12px; padding: 32px 28px; border: 1px solid rgba(80, 10, 47, 0.08);">
            <div>
                <h2 contenteditable="true" style="color: #500a2f; font-size: 2.2rem; font-weight: 600; line-height: 1.55; margin-bottom: 24px; text-align: justify;">
                    The Handloom sector is not just a vital economic contributor but a living embodiment of India’s artistic legacy. Across the country, generations of weavers have kept this heritage alive with skill, patience, and pride, producing textiles that reflect the soul of their communities.
                </h2>
                <div class="mt-4 pt-3 border-top" style="border-color: rgba(80, 10, 47, 0.15) !important;">
                    <p class="mb-2 fw-bold" style="color: #500a2f; font-size: 1.45rem;">HANDLOOM MARK SCHEME</p>
                    <p class="mb-0 text-muted" style="font-size: 1.3rem; line-height: 1.6;">OFFICE OF THE DEVELOPMENT COMMISSIONER FOR HANDLOOMS<br>MINISTRY OF TEXTILES, GOVERNMENT OF INDIA</p>
                </div>
            </div>

            <div class="mt-4 pt-3 border-top" style="border-color: rgba(80, 10, 47, 0.15) !important;">
                <h4 style="color: #500a2f; font-size: 1.5rem; font-weight: 700; margin-bottom: 12px;">Quick Links</h4>
                <ul class="list-unstyled mb-0" style="font-size: 1.35rem; line-height: 2.1;">
                    <li><a href="http://www.hlm.gov.in/" target="_blank" rel="noopener noreferrer" style="color: #500a2f; text-decoration: none;">• Handloom Mark Portal (www.hlm.gov.in)</a></li>
                    <li><a href="#scheme-overview" style="color: #500a2f; text-decoration: none;">• Scheme Overview</a></li>
                    <li><a href="#handloom-mark-logo" style="color: #500a2f; text-decoration: none;">• Handloom Mark &amp; Logo</a></li>
